    "source": "def kmp_search(text: str, pattern: str) -> list[int]:\n    \"\"\"KMP string matching — complete Python reference.\"\"\"\n    hits: list[int] = []\n    if not pattern:\n        return [0]\n    lps = build_lps(pattern)\n    i = 0\n    j = 0\n    while i < len(text):\n        if text[i] == pattern[j]:\n            i += 1\n            j += 1\n            if j == len(pattern):\n                hits.append(i - j)\n                j = lps[j - 1]\n        elif j > 0:\n            j = lps[j - 1]\n        else:\n            i += 1\n    return hits\n\n\ndef build_lps(pattern: str) -> list[int]:\n    lps = [0] * len(pattern)\n    length = 0\n    i = 1\n    while i < len(pattern):\n        if pattern[i] == pattern[length]:\n            length += 1\n            lps[i] = length\n            i += 1\n        elif length > 0:\n            length = lps[length - 1]\n        else:\n            lps[i] = 0\n            i += 1\n    return lps\n",
