    "source": "// KMP string matching — complete C++ reference.\n#include <string>\n#include <vector>\n\nstd::vector<int> buildLps(const std::string& pattern);\n\nstd::vector<int> kmpSearch(const std::string& text, const std::string& pattern) {\n  std::vector<int> hits;\n  if (pattern.empty()) return {0};\n  const std::vector<int> lps = buildLps(pattern);\n  size_t i = 0;\n  size_t j = 0;\n  while (i < text.size()) {\n    if (text[i] == pattern[j]) {\n      i++;\n      j++;\n      if (j == pattern.size()) {\n        hits.push_back(static_cast<int>(i - j));\n        j = lps[j - 1];\n      }\n    } else if (j > 0) {\n      j = lps[j - 1];\n    } else {\n      i++;\n    }\n  }\n  return hits;\n}\n\nstd::vector<int> buildLps(const std::string& pattern) {\n  std::vector<int> lps(pattern.size(), 0);\n  int len = 0;\n  size_t i = 1;\n  while (i < pattern.size()) {\n    if (pattern[i] == pattern[len]) {\n      len++;\n      lps[i] = len;\n      i++;\n    } else if (len > 0) {\n      len = lps[len - 1];\n    } else {\n      lps[i] = 0;\n      i++;\n    }\n  }\n  return lps;\n}\n",
