    "source": "/// KMP string matching — complete Rust reference.\npub fn kmp_search(text: &str, pattern: &str) -> Vec<usize> {\n    let (t, p): (Vec<char>, Vec<char>) = (text.chars().collect(), pattern.chars().collect());\n    let mut hits: Vec<usize> = Vec::new();\n    if p.is_empty() {\n        return vec![0];\n    }\n    let lps = build_lps(&p);\n    let mut i = 0;\n    let mut j = 0;\n    while i < t.len() {\n        if t[i] == p[j] {\n            i += 1;\n            j += 1;\n            if j == p.len() {\n                hits.push(i - j);\n                j = lps[j - 1];\n            }\n        } else if j > 0 {\n            j = lps[j - 1];\n        } else {\n            i += 1;\n        }\n    }\n    hits\n}\n\nfn build_lps(p: &[char]) -> Vec<usize> {\n    let mut lps = vec![0; p.len()];\n    let mut len = 0;\n    let mut i = 1;\n    while i < p.len() {\n        if p[i] == p[len] {\n            len += 1;\n            lps[i] = len;\n            i += 1;\n        } else if len > 0 {\n            len = lps[len - 1];\n        } else {\n            lps[i] = 0;\n            i += 1;\n        }\n    }\n    lps\n}\n",
