    "source": "// KMP string matching — complete Go reference.\npackage algorithms\n\n// kmpSearch returns every start index where pattern occurs in text.\nfunc kmpSearch(text, pattern string) []int {\n\thits := []int{}\n\tif len(pattern) == 0 {\n\t\treturn []int{0}\n\t}\n\tlps := buildLps(pattern)\n\ti := 0\n\tj := 0\n\tfor i < len(text) {\n\t\tif text[i] == pattern[j] {\n\t\t\ti++\n\t\t\tj++\n\t\t\tif j == len(pattern) {\n\t\t\t\thits = append(hits, i-j)\n\t\t\t\tj = lps[j-1]\n\t\t\t}\n\t\t} else if j > 0 {\n\t\t\tj = lps[j-1]\n\t\t} else {\n\t\t\ti++\n\t\t}\n\t}\n\treturn hits\n}\n\nfunc buildLps(pattern string) []int {\n\tlps := make([]int, len(pattern))\n\tlength := 0\n\ti := 1\n\tfor i < len(pattern) {\n\t\tif pattern[i] == pattern[length] {\n\t\t\tlength++\n\t\t\tlps[i] = length\n\t\t\ti++\n\t\t} else if length > 0 {\n\t\t\tlength = lps[length-1]\n\t\t} else {\n\t\t\tlps[i] = 0\n\t\t\ti++\n\t\t}\n\t}\n\treturn lps\n}\n",
